<?php
namespace App\Http\Controllers; use App\Models\{Attribute,AttributeValue}; use Illuminate\Http\Request;
class AttributeController extends Controller {public function index(){return view('admin.attributes.index',['attributes'=>Attribute::with('values')->orderBy('name')->paginate(20)]);}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:50|unique:attributes,name','values'=>'nullable|string']);$a=Attribute::create(['name'=>$d['name']]);foreach(preg_split('/[,\\n]+/',$d['values']??'') as $v){$v=trim($v);if($v)AttributeValue::create(['attribute_id'=>$a->attribute_id,'value'=>$v]);}return back()->with('success','Attribute created.');}public function destroy(Attribute $attribute){$attribute->delete();return back()->with('success','Attribute deleted.');}}
